const HSKK_PAPERS = {"beginner":{"id":"beginner","hsk":"1-2","prep":7,"minutes":20,"total":100,"pass":60,"parts":[{"part":1,"kind":"repeat","minutes":6,"items":[{"zh":"我今天很忙。","py":"Wǒ jīntiān hěn máng.","id":"Hari ini saya sangat sibuk.","en":"I am very busy today.","sec":5},{"zh":"这是我的新手机。","py":"Zhè shì wǒ de xīn shǒujī.","id":"Ini ponsel baru saya.","en":"This is my new phone.","sec":6},{"zh":"我们明天去看电影吧。","py":"Wǒmen míngtiān qù kàn diànyǐng ba.","id":"Besok kita nonton film, yuk.","en":"Let's go see a film tomorrow.","sec":6},{"zh":"他早上六点起床。","py":"Tā zǎoshang liù diǎn qǐchuáng.","id":"Dia bangun jam enam pagi.","en":"He gets up at six in the morning.","sec":6},{"zh":"你想喝茶还是喝水？","py":"Nǐ xiǎng hē chá háishi hē shuǐ?","id":"Kamu mau minum teh atau air?","en":"Would you like tea or water?","sec":6},{"zh":"我家离学校不太远。","py":"Wǒ jiā lí xuéxiào bútài yuǎn.","id":"Rumah saya tidak terlalu jauh dari sekolah.","en":"My home is not far from school.","sec":6},{"zh":"妈妈在家做饭。","py":"Māma zàijiā zuòfàn.","id":"Ibu sedang memasak di rumah.","en":"Mum is cooking at home.","sec":5},{"zh":"我的生日是九月十五号。","py":"Wǒ de shēngrì shì jiǔ yuè shí wǔ hào.","id":"Ulang tahun saya tanggal lima belas September.","en":"My birthday is the fifteenth of September.","sec":7},{"zh":"下雨了，我们回家吧。","py":"Xiàyǔ le, wǒmen huíjiā ba.","id":"Hujan turun, ayo kita pulang.","en":"It's raining, let's go home.","sec":6},{"zh":"我坐公共汽车去上班。","py":"Wǒ zuò gōnggòngqìchē qù shàngbān.","id":"Saya naik bus ke kantor.","en":"I take the bus to work.","sec":6},{"zh":"这件衣服多少钱？","py":"Zhè jiàn yīfu duōshao qián?","id":"Baju ini berapa harganya?","en":"How much is this piece of clothing?","sec":6},{"zh":"我昨天晚上没睡好。","py":"Wǒ zuótiān wǎnshang méi shuì hǎo.","id":"Tadi malam saya tidak tidur nyenyak.","en":"I didn't sleep well last night.","sec":6},{"zh":"他汉语说得很好。","py":"Tā Hànyǔ shuō de hěn hǎo.","id":"Bahasa Mandarinnya sangat bagus.","en":"He speaks Chinese very well.","sec":6},{"zh":"我们一起去吃饭吧。","py":"Wǒmen yìqǐ qù chīfàn ba.","id":"Ayo kita makan bersama.","en":"Let's go and eat together.","sec":6},{"zh":"请你慢一点儿说。","py":"Qǐng nǐ màn yìdiǎnr shuō.","id":"Tolong bicara lebih pelan.","en":"Please speak a bit more slowly.","sec":6}],"points":46},{"part":2,"kind":"answer","minutes":4,"items":[{"zh":"你叫什么名字？","py":"Nǐ jiào shénme míngzi?","id":"Siapa namamu? - Nama saya Wang Xiaoming.","en":"What is your name? - My name is Wang Xiaoming.","sec":10,"model":"我叫王小明。","model_py":"Wǒ jiào Wáng Xiǎomíng."},{"zh":"你家有几口人？","py":"Nǐ jiā yǒu jǐ kǒu rén?","id":"Ada berapa orang di keluargamu? - Ada empat orang.","en":"How many people are in your family? - Four.","sec":10,"model":"我家有四口人。","model_py":"Wǒ jiā yǒu sì kǒu rén."},{"zh":"你今天几点起床的？","py":"Nǐ jīntiān jǐ diǎn qǐchuáng de?","id":"Jam berapa kamu bangun hari ini? - Jam tujuh.","en":"What time did you get up today? - At seven.","sec":10,"model":"我今天七点起床的。","model_py":"Wǒ jīntiān qī diǎn qǐchuáng de."},{"zh":"你喜欢吃什么？","py":"Nǐ xǐhuan chī shénme?","id":"Kamu suka makan apa? - Saya suka nasi dan telur.","en":"What do you like to eat? - I like rice and eggs.","sec":10,"model":"我喜欢吃米饭和鸡蛋。","model_py":"Wǒ xǐhuan chī mǐfàn hé jīdàn."},{"zh":"你喜欢什么运动？","py":"Nǐ xǐhuan shénme yùndòng?","id":"Kamu suka olahraga apa? - Saya suka main basket.","en":"What sport do you like? - I like basketball.","sec":10,"model":"我喜欢打篮球。","model_py":"Wǒ xǐhuan dǎ lánqiú."},{"zh":"现在几点了？","py":"Xiànzài jǐ diǎn le?","id":"Sekarang jam berapa? - Jam setengah empat sore.","en":"What time is it now? - Half past three in the afternoon.","sec":10,"model":"现在下午三点半。","model_py":"Xiànzài xiàwǔ sān diǎn bàn."},{"zh":"你怎么去学校？","py":"Nǐ zěnme qù xuéxiào?","id":"Kamu ke sekolah naik apa? - Naik sepeda.","en":"How do you get to school? - By bike.","sec":10,"model":"我骑自行车去学校。","model_py":"Wǒ qí zìxíngchē qù xuéxiào."},{"zh":"你会说汉语吗？","py":"Nǐ huì shuō Hànyǔ ma?","id":"Kamu bisa bahasa Mandarin? - Bisa, sedikit.","en":"Can you speak Chinese? - Yes, a little.","sec":10,"model":"会，我会说一点儿汉语。","model_py":"Huì, wǒ huì shuō yìdiǎnr Hànyǔ."},{"zh":"今天天气怎么样？","py":"Jīntiān tiānqì zěnmeyàng?","id":"Bagaimana cuaca hari ini? - Bagus, tidak dingin dan tidak panas.","en":"How is the weather today? - Nice, neither cold nor hot.","sec":10,"model":"今天天气很好，不冷也不热。","model_py":"Jīntiān tiānqì hěn hǎo, bù lěng yě bú rè."},{"zh":"你住在哪儿？","py":"Nǐ zhù zài nǎr?","id":"Kamu tinggal di mana? - Di sebelah sekolah.","en":"Where do you live? - Next to the school.","sec":10,"model":"我住在学校旁边。","model_py":"Wǒ zhù zài xuéxiào pángbiān."}],"points":31},{"part":3,"kind":"open","minutes":3,"items":[{"zh":"请介绍一下你的家人。","py":"Qǐng jièshào yíxià nǐ de jiārén.","id":"Tolong perkenalkan keluargamu.","en":"Please introduce your family.","sec":90,"model":"我家有四口人：爸爸、妈妈、哥哥和我。爸爸是医生，他工作很忙。妈妈是老师，她很喜欢唱歌。哥哥今年二十岁，他是大学生。我们周末常常一起吃饭、看电视。我很爱我的家人。","model_py":"Wǒ jiā yǒu sì kǒu rén: bàba, māma, gēge hé wǒ. Bàba shì yīshēng, tā gōngzuò hěn máng. Māma shì lǎoshī, tā hěn xǐhuan chànggē. Gēge jīnnián èr shí suì, tā shì dàxuéshēng. Wǒmen zhōumò chángcháng yìqǐ chīfàn, kàn diànshì. Wǒ hěn ài wǒ de jiārén."},{"zh":"你最喜欢做什么？为什么？","py":"Nǐ zuì xǐhuan zuò shénme? Wèishénme?","id":"Apa yang paling kamu suka lakukan? Kenapa?","en":"What do you like doing most? Why?","sec":90,"model":"我最喜欢打篮球。我上大学的时候就打篮球了。打球对身体很好，打完球以后我觉得很高兴。周末我常常和朋友一起去学校打球，打完以后我们一起去吃饭、说话。","model_py":"Wǒ zuì xǐhuan dǎ lánqiú. Wǒ shàng dàxué de shíhou jiù dǎ lánqiú le. Dǎqiú duì shēntǐ hěn hǎo, dǎ wán qiú yǐhòu wǒ juéde hěn gāoxìng. Zhōumò wǒ chángcháng hé péngyou yìqǐ qù xuéxiào dǎqiú, dǎ wán yǐhòu wǒmen yìqǐ qù chīfàn, shuōhuà."}],"points":23}]},"intermediate":{"id":"intermediate","hsk":"3-4","prep":10,"minutes":23,"total":100,"pass":60,"parts":[{"part":1,"kind":"repeat","minutes":5,"items":[{"zh":"我已经习惯了这里的天气。","py":"Wǒ yǐjīng xíguàn le zhèlǐ de tiānqì.","id":"Saya sudah terbiasa dengan cuaca di sini.","en":"I have got used to the weather here.","sec":8},{"zh":"如果明天不下雨，我们就去爬山。","py":"Rúguǒ míngtiān bú xiàyǔ, wǒmen jiù qù páshān.","id":"Kalau besok tidak hujan, kita naik gunung.","en":"If it doesn't rain tomorrow, we'll go hiking.","sec":8},{"zh":"这家饭馆的菜又便宜又好吃。","py":"Zhè jiā fànguǎn de cài yòu piányi yòu hǎochī.","id":"Masakan di restoran ini murah dan enak.","en":"The food at this restaurant is cheap and tasty.","sec":8},{"zh":"他把作业忘在教室里了。","py":"Tā bǎ zuòyè wàng zài jiàoshì lǐ le.","id":"Dia lupa membawa PR-nya, tertinggal di kelas.","en":"He left his homework in the classroom.","sec":7},{"zh":"虽然工作很累，但是我很喜欢。","py":"Suīrán gōngzuò hěn lèi, dànshì wǒ hěn xǐhuan.","id":"Meskipun pekerjaannya melelahkan, saya menyukainya.","en":"Although the work is tiring, I like it.","sec":8},{"zh":"请你帮我把这本书还给图书馆。","py":"Qǐng nǐ bāng wǒ bǎ zhè běn shū huán gěi túshūguǎn.","id":"Tolong kembalikan buku ini ke perpustakaan untuk saya.","en":"Please return this book to the library for me.","sec":8},{"zh":"我打算放假的时候去北京旅游。","py":"Wǒ dǎsuàn fàngjià de shíhou qù Běijīng lǚyóu.","id":"Saya berencana berlibur ke Beijing saat liburan.","en":"I plan to travel to Beijing during the holiday.","sec":8},{"zh":"这个问题比我想的复杂多了。","py":"Zhège wèntí bǐ wǒ xiǎng de fùzá duō le.","id":"Masalah ini jauh lebih rumit dari yang saya kira.","en":"This problem is much more complicated than I thought.","sec":8},{"zh":"他一边听音乐一边做作业。","py":"Tā yìbiān tīng yīnyuè yìbiān zuò zuòyè.","id":"Dia mengerjakan PR sambil mendengarkan musik.","en":"He does his homework while listening to music.","sec":8},{"zh":"只要多练习，你的汉语一定会越来越好。","py":"Zhǐyào duō liànxí, nǐ de Hànyǔ yídìng huì yuèláiyuè hǎo.","id":"Asal banyak berlatih, bahasa Mandarinmu pasti makin bagus.","en":"As long as you practise a lot, your Chinese will keep getting better.","sec":10}],"points":38},{"part":2,"kind":"picture","minutes":4,"items":[{"zh":"请说一说这张图片。","py":"Qǐng shuō yi shuō zhè zhāng túpiàn.","id":"Ceritakan isi gambar ini.","en":"Describe this picture.","sec":120,"pics":["store","shopping-cart","apple","banknote"],"model":"周末，我和妈妈一起去超市买东西。超市里人很多，东西也很多。我们推着购物车，先买了一些水果，比如苹果和香蕉，然后又买了牛奶和面包。最后我们去付钱，一共花了一百多块。虽然有点儿累，但是我们买到了一个星期需要的东西，我觉得很高兴。","model_py":"Zhōumò, wǒ hé māma yìqǐ qù chāoshì mǎi dōngxi. Chāoshì lǐ rén hěn duō, dōngxi yě hěn duō. Wǒmen tuī zhe gòuwù chē, xiān mǎi le yìxiē shuǐguǒ, bǐrú píngguǒ hé xiāngjiāo, ránhòu yòu mǎi le niúnǎi hé miànbāo. Zuìhòu wǒmen qù fù qián, yígòng huā le yì bǎi duō kuài. Suīrán yǒudiǎnr lèi, dànshì wǒmen mǎi dào le yí gè xīngqī xūyào de dōngxi, wǒ juéde hěn gāoxìng."},{"zh":"请说一说这张图片。","py":"Qǐng shuō yi shuō zhè zhāng túpiàn.","id":"Ceritakan isi gambar ini.","en":"Describe this picture.","sec":120,"pics":["plane","map","hotel","ticket"],"model":"这张图片说的是旅游。放假以前，我们先在网上买好了飞机票，也找好了酒店。到了以后，我们拿着地图，一边走一边看。那个城市很漂亮，有很多有名的地方。晚上我们回到酒店休息，第二天再去别的地方参观。这次旅游让我认识了很多新朋友。","model_py":"Zhè zhāng túpiàn shuō de shì lǚyóu. Fàngjià yǐqián, wǒmen xiān zài wǎngshàng mǎi hǎo le fēijī piào, yě zhǎo hǎo le jiǔdiàn. Dào le yǐhòu, wǒmen ná zhe dìtú, yìbiān zǒu yìbiān kàn. Nàge chéngshì hěn piàoliang, yǒu hěn duō yǒumíng de dìfang. Wǎnshang wǒmen huídào jiǔdiàn xiūxi, dì'èr tiān zài qù biéde dìfang cānguān. Zhè cì lǚyóu ràng wǒ rènshi le hěn duō xīn péngyou."}],"points":31},{"part":3,"kind":"open","minutes":4,"items":[{"zh":"你觉得学习汉语最难的是什么？为什么？","py":"Nǐ juéde xuéxí Hànyǔ zuì nán de shì shénme? Wèishénme?","id":"Menurutmu apa yang paling sulit dalam belajar bahasa Mandarin? Kenapa?","en":"What do you think is the hardest part of learning Chinese? Why?","sec":120,"model":"我觉得学习汉语最难的是四个声调。声调不一样，意思就不一样。比如“妈”和“马”，只是声调不同，可是意思完全不同。刚开始的时候，我常常说错，别人听不懂。后来我每天听录音，跟着练习，现在已经好多了。我觉得只要多听多说，就一定能学好。","model_py":"Wǒ juéde xuéxí Hànyǔ zuì nán de shì sì gè shēngdiào. Shēngdiào bù yíyàng, yìsi jiù bù yíyàng. Bǐrú “mā” hé “mǎ”, zhǐshì shēngdiào bùtóng, kěshì yìsi wánquán bùtóng. Gāng kāishǐ de shíhou, wǒ chángcháng shuō cuò, biéren tīng bù dǒng. Hòulái wǒ měi tiān tīng lùyīn, gēn zhe liànxí, xiànzài yǐjīng hǎoduō le. Wǒ juéde zhǐyào duō tīng duō shuō, jiù yídìng néng xué hǎo."},{"zh":"你喜欢住在城市还是农村？请说说你的理由。","py":"Nǐ xǐhuan zhù zài chéngshì háishi nóngcūn? Qǐng shuōshuo nǐ de lǐyóu.","id":"Kamu lebih suka tinggal di kota atau di desa? Jelaskan alasannya.","en":"Would you rather live in a city or in the countryside? Give your reasons.","sec":120,"model":"我更喜欢住在城市。第一，城市的交通很方便，去哪儿都可以坐地铁或者公共汽车。第二，城市里有很多商店、医院和学校，生活很方便。第三，城市的工作机会比较多。当然，城市也有缺点，比如人太多，空气不太好。不过总的来说，我还是喜欢城市的生活。","model_py":"Wǒ gèng xǐhuan zhù zài chéngshì. Dì yī, chéngshì de jiāotōng hěn fāngbiàn, qù nǎr dōu kěyǐ zuò dìtiě huòzhě gōnggòngqìchē. Dì'èr, chéngshì lǐ yǒu hěn duō shāngdiàn, yīyuàn hé xuéxiào, shēnghuó hěn fāngbiàn. Dì sān, chéngshì de gōngzuò jīhuì bǐjiào duō. Dāngrán, chéngshì yě yǒu quēdiǎn, bǐrú rén tài duō, kōngqì bútài hǎo. Búguò zǒng de lái shuō, wǒ háishi xǐhuan chéngshì de shēnghuó."}],"points":31}]},"advanced":{"id":"advanced","hsk":"5-6","prep":10,"minutes":25,"total":100,"pass":60,"parts":[{"part":1,"kind":"retell","minutes":8,"items":[{"zh":"古时候，有几个人得到了一壶酒，可是酒不够大家喝。于是他们决定比赛画蛇，谁先画完，酒就归谁。有一个人很快就画好了，他看别人还没画完，就得意地给蛇加上了脚。这时另一个人也画完了，他抢过酒说：“蛇本来没有脚，你画的不是蛇。”说完就把酒喝了。","py":"Gǔ shíhou, yǒu jǐ gè rén dédào le yì hú jiǔ, kěshì jiǔ búgòu dàjiā hē. Yúshì tāmen juédìng bǐsài huà shé, shéi xiān huà wán, jiǔ jiù guī shéi. Yǒu yí gè rén hěn kuài jiù huà hǎo le, tā kàn biéren hái méi huà wán, jiù déyì de gěi shé jiāshàng le jiǎo. Zhèshí lìng yí gè rén yě huà wánle, tā qiǎng guò jiǔ shuō: “shé běnlái méiyǒu jiǎo, nǐ huà de bú shì shé.” Shuō wán jiù bǎ jiǔ hē le.","id":"Dahulu kala beberapa orang mendapat satu kendi arak, tapi tidak cukup untuk semua. Mereka berlomba menggambar ular; yang pertama selesai mendapat araknya. Satu orang selesai paling cepat, lalu dengan bangga menambahkan kaki pada ularnya. Orang lain yang selesai kemudian merebut arak itu dan berkata: ular tidak punya kaki, jadi gambarmu bukan ular.","en":"Long ago some people got a jug of wine that was not enough for all. They held a snake-drawing race; the first to finish would get the wine. One man finished first and, pleased with himself, added feet to his snake. The next man to finish grabbed the wine, saying snakes have no feet, so his drawing was not a snake.","sec":120},{"zh":"现在越来越多的人喜欢在网上购物。网上购物有很多好处：东西的种类多，价格往往比商店便宜，而且不用出门，商品就能送到家里。但是网上购物也有缺点，比如看不到真正的商品，有时候收到的东西和图片上不一样，退货也比较麻烦。所以，网上购物的时候一定要选择信用好的商店。","py":"Xiànzài yuèláiyuè duō de rén xǐhuan zài wǎngshàng gòuwù. Wǎngshàng gòuwù yǒu hěn duō hǎochu: dōngxi de zhǒnglèi duō, jiàgé wǎngwǎng bǐ shāngdiàn piányi, érqiě búyòng chūmén, shāngpǐn jiù néng sòngdào jiālǐ. Dànshì wǎngshàng gòuwù yě yǒu quēdiǎn, bǐrú kàn bú dào zhēnzhèng de shāngpǐn, yǒushíhou shōudào de dōngxi hé túpiàn shàng bù yíyàng, tuì huò yě bǐjiào máfan. Suǒyǐ, wǎngshàng gòuwù de shíhou yídìng yào xuǎnzé xìnyòng hǎo de shāngdiàn.","id":"Makin banyak orang suka belanja online: pilihan barang banyak, harga sering lebih murah, dan barang diantar ke rumah. Tapi ada kekurangannya: barang tidak bisa dilihat langsung, kadang berbeda dari foto, dan pengembalian barang merepotkan. Jadi pilihlah penjual yang terpercaya.","en":"More and more people shop online: there is more choice, prices are often lower and goods are delivered home. But you cannot see the real item, it sometimes differs from the photo, and returns are a hassle. So choose sellers with a good reputation.","sec":120},{"zh":"小李刚开始工作的时候，每天都觉得时间不够用。后来他发现，问题不在于时间太少，而在于他没有计划。于是他每天早上先把要做的事情写下来，再按照重要程度排好顺序。一个月以后，他不但能按时完成工作，而且下班以后还有时间锻炼身体。他说，好的习惯比聪明更重要。","py":"Xiǎo Lǐ gāng kāishǐ gōngzuò de shíhou, měi tiān dōu juéde shíjiān búgòu yòng. Hòulái tā fāxiàn, wèntí bú zàiyú shíjiān tài shǎo, ér zàiyú tā méiyǒu jìhuà. Yúshì tā měi tiān zǎoshang xiān bǎ yào zuò de shìqing xiě xiàlai, zài ànzhào zhòngyào chéngdù pái hǎo shùnxù. Yí gè yuè yǐhòu, tā búdàn néng ànshí wánchéng gōngzuò, érqiě xiàbān yǐhòu háiyǒu shíjiān duànliàn shēntǐ. Tā shuō, hǎo de xíguàn bǐ cōngming gèng zhòngyào.","id":"Saat baru mulai bekerja, Xiao Li selalu merasa waktunya kurang. Ia lalu sadar masalahnya bukan waktu, tapi tidak punya rencana. Setiap pagi ia menulis tugasnya dan mengurutkan menurut pentingnya. Sebulan kemudian pekerjaannya selesai tepat waktu dan ia masih sempat berolahraga. Katanya, kebiasaan baik lebih penting daripada pintar.","en":"When Xiao Li started work he never had enough time. He realised the problem was not too little time but no plan. Each morning he wrote down his tasks and ranked them by importance. A month later he finished work on time and still had time to exercise. Good habits, he says, matter more than being clever.","sec":120}],"points":53},{"part":2,"kind":"read","minutes":2,"items":[{"zh":"每个人都会遇到困难。有的人遇到困难就放弃了，有的人却把困难当成机会。其实，困难并不可怕，可怕的是失去信心。当我们遇到问题的时候，最好先冷静下来，分析问题的原因，再一步一步地去解决。在这个过程中，我们不仅能学到新的知识，还能变得更加成熟。很多成功的人都说，正是那些困难的经历，让他们成为了今天的自己。所以，与其害怕困难，不如勇敢地面对它。","py":"Měi gè rén dōu huì yùdào kùnnan. Yǒude rén yùdào kùnnan jiù fàngqì le, yǒude rén què bǎ kùnnan dàngchéng jīhuì. Qíshí, kùnnan bìng bù kěpà, kěpà de shì shīqù xìnxīn. Dāng wǒmen yùdào wèntí de shíhou, zuìhǎo xiān lěngjìng xiàlai, fēnxī wèntí de yuányīn, zài yí bù yí bù de qù jiějué. Zài zhège guòchéng zhōng, wǒmen bùjǐn néng xué dào xīn de zhīshi, hái néng biàn de gèngjiā chéngshú. Hěn duō chénggōng de rén dōu shuō, zhèngshì nàxiē kùnnan de jīnglì, ràng tāmen chéngwéi le jīntiān de zìjǐ. Suǒyǐ, yǔ qí hàipà kùnnan, bùrú yǒnggǎn de miànduì tā.","id":"Setiap orang akan menghadapi kesulitan. Ada yang menyerah, ada yang menjadikannya kesempatan. Kesulitan tidak menakutkan; yang menakutkan adalah kehilangan kepercayaan diri. Saat ada masalah, tenangkan diri, analisis penyebabnya, lalu selesaikan selangkah demi selangkah. Dalam prosesnya kita belajar hal baru dan menjadi lebih dewasa. Banyak orang sukses berkata pengalaman sulit itulah yang membentuk mereka. Jadi, daripada takut, hadapilah dengan berani.","en":"Everyone meets difficulties. Some give up; others treat them as chances. Difficulty is not frightening; losing confidence is. When a problem comes, calm down, analyse its cause and solve it step by step. Along the way we learn and grow more mature. Many successful people say those hard experiences made them who they are. So rather than fear difficulty, face it bravely.","sec":120}],"points":13},{"part":3,"kind":"open","minutes":5,"items":[{"zh":"有人说“失败是成功之母”，你同意这个观点吗？为什么？","py":"Yǒurén shuō “shībài shì chénggōng zhī mǔ”, nǐ tóngyì zhège guāndiǎn ma? Wèishénme?","id":"Ada yang bilang 'kegagalan adalah ibu dari kesuksesan'. Setujukah kamu? Kenapa?","en":"Some say 'failure is the mother of success'. Do you agree? Why?","sec":150,"model":"我基本同意这个观点。失败能让我们发现自己的不足，从而找到改进的方法。比如我第一次参加汉语考试的时候没有通过，后来我认真分析了原因，发现自己的听力比较差，于是每天坚持听新闻，第二次就顺利通过了。不过，我认为失败本身并不会自动带来成功，关键在于我们能不能从失败中总结经验。如果一个人失败以后只会抱怨，那么失败就只是失败。","model_py":"Wǒ jīběn tóngyì zhège guāndiǎn. Shībài néng ràng wǒmen fāxiàn zìjǐ de bùzú, cóng'ér zhǎodào gǎijìn de fāngfǎ. Bǐrú wǒ dì yī cì cānjiā Hànyǔ kǎoshì de shíhou méiyǒu tōngguò, hòulái wǒ rènzhēn fēnxī le yuányīn, fāxiàn zìjǐ de tīnglì bǐjiào chà, yúshì měi tiān jiānchí tīng xīnwén, dì'èr cì jiù shùnlì tōngguò le. Búguò, wǒ rènwéi shībài běnshēn bìng bú huì zìdòng dàilái chénggōng, guānjiàn zàiyú wǒmen néngbùnéng cóng shībài zhōng zǒngjié jīngyàn. Rúguǒ yí gè rén shībài yǐhòu zhǐ huì bàoyuàn, nàme shībài jiù zhǐshì shībài."},{"zh":"你认为互联网对人们的生活有哪些影响？","py":"Nǐ rènwéi Hùliánwǎng duì rénmen de shēnghuó yǒu nǎxiē yǐngxiǎng?","id":"Menurutmu apa saja pengaruh internet terhadap kehidupan orang?","en":"What effects do you think the internet has on people's lives?","sec":150,"model":"我认为互联网对生活的影响既有积极的一面，也有消极的一面。积极的方面是，互联网让信息的传播变得非常快，我们可以随时了解世界各地的新闻，也可以在网上学习、工作和购物，生活方便了很多。消极的方面是，有些人在网上花的时间太多，影响了身体健康和与家人的交流，网上的信息也不一定都是真的。所以，我们应该合理地使用互联网。","model_py":"Wǒ rènwéi Hùliánwǎng duì shēnghuó de yǐngxiǎng jì yǒu jījí de yí miàn, yě yǒu xiāojí de yí miàn. Jījí de fāngmiàn shì, Hùliánwǎng ràng xìnxī de chuánbō biàn de fēicháng kuài, wǒmen kěyǐ suíshí liǎojiě shìjiè gèdì de xīnwén, yě kěyǐ zài wǎngshàng xuéxí, gōngzuò hé gòuwù, shēnghuó fāngbiàn le hěn duō. Xiāojí de fāngmiàn shì, yǒuxiē rén zài wǎngshàng huā de shíjiān tài duō, yǐngxiǎng le shēntǐ jiànkāng hé yǔ jiārén de jiāoliú, wǎngshàng de xìnxī yě bùyídìng dōu shì zhēnde. Suǒyǐ, wǒmen yīnggāi hélǐ de shǐyòng Hùliánwǎng."}],"points":34}]}};

// Set B (Paket B): a second original paper per level, same format and timing as Set A, no repeated sentences.
const HSKK_PAPERS_B = {"beginner":{"id":"beginner","hsk":"1-2","prep":7,"minutes":20,"total":100,"pass":60,"set":"B","parts":[{"part":1,"kind":"repeat","minutes":6,"items":[{"zh":"我明天不上班。","py":"Wǒ míngtiān bú shàngbān.","id":"Besok saya tidak masuk kerja.","en":"I am not working tomorrow.","sec":6},{"zh":"这个西瓜很好吃。","py":"Zhège xīguā hěn hǎochī.","id":"Semangka ini enak sekali.","en":"This watermelon is delicious.","sec":6},{"zh":"你家有几个房间？","py":"Nǐ jiā yǒu jǐ ge fángjiān?","id":"Rumahmu punya berapa kamar?","en":"How many rooms does your home have?","sec":6},{"zh":"我想买一本汉语书。","py":"Wǒ xiǎng mǎi yìběn Hànyǔ shū.","id":"Saya mau membeli sebuah buku bahasa Mandarin.","en":"I want to buy a Chinese book.","sec":6},{"zh":"他早上常常去运动。","py":"Tā zǎoshang chángcháng qù yùndòng.","id":"Pagi hari dia sering pergi berolahraga.","en":"He often goes to exercise in the morning.","sec":6},{"zh":"今天比昨天冷。","py":"Jīntiān bǐ zuótiān lěng.","id":"Hari ini lebih dingin daripada kemarin.","en":"Today is colder than yesterday.","sec":6},{"zh":"我的朋友在医院工作。","py":"Wǒ de péngyou zài yīyuàn gōngzuò.","id":"Teman saya bekerja di rumah sakit.","en":"My friend works at a hospital.","sec":6},{"zh":"火车站在哪儿？","py":"Huǒchēzhàn zài nǎr?","id":"Stasiun kereta di mana?","en":"Where is the train station?","sec":6},{"zh":"我们下午三点见面吧。","py":"Wǒmen xiàwǔ sāndiǎn jiànmiàn ba.","id":"Kita bertemu jam tiga sore, ya.","en":"Let's meet at three in the afternoon.","sec":6},{"zh":"桌子上有两杯茶。","py":"Zhuōzi shàng yǒu liǎngbēi chá.","id":"Di atas meja ada dua gelas teh.","en":"There are two cups of tea on the table.","sec":6},{"zh":"她是我的汉语老师。","py":"Tā shì wǒ de Hànyǔ lǎoshī.","id":"Dia guru bahasa Mandarin saya.","en":"She is my Chinese teacher.","sec":6},{"zh":"你吃饭了吗？","py":"Nǐ chīfàn le ma?","id":"Kamu sudah makan?","en":"Have you eaten?","sec":5},{"zh":"我觉得这件衣服有点儿大。","py":"Wǒ juéde zhèjiàn yīfu yǒudiǎnr dà.","id":"Menurut saya baju ini agak besar.","en":"I think this piece of clothing is a bit big.","sec":7},{"zh":"下雪了，你多穿点儿衣服。","py":"Xiàxuě le, nǐ duō chuān diǎnr yīfu.","id":"Turun salju, pakailah baju lebih tebal.","en":"It's snowing, wear more clothes.","sec":7},{"zh":"我女儿今年六岁了。","py":"Wǒ nǚ'ér jīnnián liùsuì le.","id":"Putri saya tahun ini sudah enam tahun.","en":"My daughter is six this year.","sec":6}],"points":46},{"part":2,"kind":"answer","minutes":4,"items":[{"zh":"你今年多大了？","py":"Nǐ jīnnián duō dà le?","id":"Umurmu berapa tahun ini? - Dua puluh lima tahun.","en":"How old are you this year? - Twenty-five.","sec":10,"model":"我今年二十五岁。","model_py":"Wǒ jīnnián èrshíwǔsuì."},{"zh":"你是哪国人？","py":"Nǐ shì nǎ guó rén?","id":"Kamu orang mana? - Saya orang Indonesia.","en":"Where are you from? - I am Indonesian.","sec":10,"model":"我是印度尼西亚人。","model_py":"Wǒ shì Yìndùníxīyà rén."},{"zh":"你喜欢喝牛奶还是喝茶？","py":"Nǐ xǐhuan hē niúnǎi háishi hēchá?","id":"Kamu lebih suka susu atau teh? - Saya suka teh.","en":"Do you prefer milk or tea? - I like tea.","sec":10,"model":"我喜欢喝茶。","model_py":"Wǒ xǐhuan hēchá."},{"zh":"今天星期几？","py":"Jīntiān xīngqī jǐ?","id":"Hari ini hari apa? - Hari Rabu.","en":"What day is it today? - Wednesday.","sec":10,"model":"今天星期三。","model_py":"Jīntiān xīngqīsān."},{"zh":"你的手机是什么颜色的？","py":"Nǐ de shǒujī shì shénme yánsè de?","id":"Ponselmu warna apa? - Hitam.","en":"What colour is your phone? - Black.","sec":10,"model":"我的手机是黑色的。","model_py":"Wǒ de shǒujī shì hēisè de."},{"zh":"你晚上几点睡觉？","py":"Nǐ wǎnshang jǐdiǎn shuìjiào?","id":"Malam hari kamu tidur jam berapa? - Jam sebelas malam.","en":"What time do you go to bed? - At eleven at night.","sec":10,"model":"我晚上十一点睡觉。","model_py":"Wǒ wǎnshang shíyī diǎn shuìjiào."},{"zh":"你周末喜欢做什么？","py":"Nǐ zhōumò xǐhuan zuò shénme?","id":"Akhir pekan kamu suka melakukan apa? - Membaca buku di rumah.","en":"What do you like doing at weekends? - Reading at home.","sec":10,"model":"我周末喜欢在家看书。","model_py":"Wǒ zhōumò xǐhuan zàijiā kànshū."},{"zh":"你学汉语多长时间了？","py":"Nǐ xué Hànyǔ duō cháng shíjiān le?","id":"Sudah berapa lama kamu belajar bahasa Mandarin? - Satu tahun.","en":"How long have you been learning Chinese? - One year.","sec":10,"model":"我学汉语一年了。","model_py":"Wǒ xué Hànyǔ yìnián le."},{"zh":"你家离商店远吗？","py":"Nǐ jiā lí shāngdiàn yuǎn ma?","id":"Rumahmu jauh dari toko? - Tidak jauh, jalan lima menit sudah sampai.","en":"Is your home far from the shop? - No, it's a five-minute walk.","sec":10,"model":"不远，走五分钟就到了。","model_py":"Bùyuǎn, zǒu wǔfēnzhōng jiù dào le."},{"zh":"你昨天去哪儿了？","py":"Nǐ zuótiān qù nǎr le?","id":"Kemarin kamu ke mana? - Ke rumah teman.","en":"Where did you go yesterday? - To a friend's home.","sec":10,"model":"我昨天去朋友家了。","model_py":"Wǒ zuótiān qù péngyou jiā le."}],"points":31},{"part":3,"kind":"open","minutes":3,"items":[{"zh":"请说说你的一天。","py":"Qǐng shuōshuo nǐ de yìtiān.","id":"Ceritakan satu harimu.","en":"Please talk about your day.","sec":90,"model":"我早上七点起床，起床以后喝一杯牛奶，吃一个鸡蛋。八点我坐公共汽车去公司。中午我和同事一起在公司旁边吃饭。下午五点半下班，回家以后我先做饭，再看一会儿电视。晚上十点半我就睡觉了。我觉得我的一天很忙，但是很快乐。","model_py":"Wǒ zǎoshang qīdiǎn qǐchuáng, qǐchuáng yǐhòu hē yì bēi niúnǎi, chī yí ge jīdàn. Bādiǎn wǒ zuò gōnggòngqìchē qù gōngsī. Zhōngwǔ wǒ hé tóngshì yìqǐ zài gōngsī pángbiān chīfàn. Xiàwǔ wǔdiǎn bàn xiàbān, huíjiā yǐhòu wǒ xiān zuòfàn, zài kàn yíhuìr diànshì. Wǎnshang shídiǎn bàn wǒ jiù shuìjiào le. Wǒ juéde wǒ de yìtiān hěn máng, dànshì hěn kuàilè."},{"zh":"你最好的朋友是谁？请介绍一下。","py":"Nǐ zuìhǎo de péngyou shì shuí? Qǐng jièshào yíxià.","id":"Siapa teman terbaikmu? Tolong perkenalkan.","en":"Who is your best friend? Please introduce them.","sec":90,"model":"我最好的朋友叫李红，我们是大学同学。她个子很高，眼睛很大，非常爱笑。她喜欢唱歌，也喜欢做饭，她做的菜特别好吃。我们认识六年了，有时间的时候常常一起去看电影、买东西。我有问题的时候，她常常帮助我。我很高兴有这么好的朋友。","model_py":"Wǒ zuìhǎo de péngyou jiào Lǐ Hóng, wǒmen shì dàxué tóngxué. Tā gèzi hěn gāo, yǎnjing hěndà, fēicháng ài xiào. Tā xǐhuan chànggē, yě xǐhuan zuòfàn, tā zuò de cài tèbié hǎochī. Wǒmen rènshi liùnián le, yǒu shíjiān de shíhou chángcháng yìqǐ qù kàn diànyǐng, mǎi dōngxi. Wǒ yǒu wèntí de shíhou, tā chángcháng bāngzhù wǒ. Wǒ hěn gāoxìng yǒu zhème hǎo de péngyou."}],"points":23}]},"intermediate":{"id":"intermediate","hsk":"3-4","prep":10,"minutes":23,"total":100,"pass":60,"set":"B","parts":[{"part":1,"kind":"repeat","minutes":5,"items":[{"zh":"我们最好提前十分钟到机场。","py":"Wǒmen zuìhǎo tíqián shífēnzhōng dào jīchǎng.","id":"Sebaiknya kita tiba di bandara sepuluh menit lebih awal.","en":"We had better get to the airport ten minutes early.","sec":8},{"zh":"这个周末我得在家准备考试。","py":"Zhège zhōumò wǒ děi zài jiā zhǔnbèi kǎoshì.","id":"Akhir pekan ini saya harus di rumah bersiap untuk ujian.","en":"This weekend I have to stay home and prepare for the exam.","sec":8},{"zh":"他的房间打扫得非常干净。","py":"Tā de fángjiān dǎsǎo de fēicháng gānjìng.","id":"Kamarnya dibersihkan sampai sangat bersih.","en":"His room has been cleaned spotless.","sec":8},{"zh":"你能不能把空调关小一点儿？","py":"Nǐ néng bu néng bǎ kōngtiáo guān xiǎo yìdiǎnr?","id":"Bisakah kamu mengecilkan AC sedikit?","en":"Could you turn the air conditioning down a bit?","sec":8},{"zh":"因为路上堵车，所以我迟到了。","py":"Yīnwèi lùshàng dǔchē, suǒyǐ wǒ chídào le.","id":"Karena jalanan macet, saya terlambat.","en":"Because of the traffic jam, I was late.","sec":8},{"zh":"这次比赛我们班得了第一名。","py":"Zhècì bǐsài wǒmen bān dé le dì yī míng.","id":"Di lomba kali ini kelas kami juara pertama.","en":"Our class came first in this competition.","sec":8},{"zh":"我几乎忘了今天是你的生日。","py":"Wǒ jīhū wàng le jīntiān shì nǐ de shēngrì.","id":"Saya hampir lupa hari ini ulang tahunmu.","en":"I almost forgot today is your birthday.","sec":8},{"zh":"你要是累了，就先回去休息吧。","py":"Nǐ yàoshì lèi le, jiù xiān huíqù xiūxi ba.","id":"Kalau kamu capek, pulanglah dulu untuk istirahat.","en":"If you are tired, go back and rest first.","sec":8},{"zh":"经理让我把这份材料复印三份。","py":"Jīnglǐ ràng wǒ bǎ zhèfèn cáiliào fùyìn sānfèn.","id":"Manajer menyuruh saya memfotokopi dokumen ini tiga rangkap.","en":"The manager asked me to make three copies of this document.","sec":8},{"zh":"不管天气怎么样，他每天都去公园散步。","py":"Bùguǎn tiānqì zěnmeyàng, tā měitiān dōu qù gōngyuán sànbù.","id":"Apa pun cuacanya, dia berjalan-jalan di taman setiap hari.","en":"Whatever the weather, he walks in the park every day.","sec":10}],"points":38},{"part":2,"kind":"picture","minutes":4,"items":[{"zh":"请说一说这张图片。","py":"Qǐng shuō yi shuō zhè zhāng túpiàn.","id":"Ceritakan isi gambar ini.","en":"Describe this picture.","sec":120,"pics":["cooking-pot","soup","utensils","gift"],"model":"今天是妈妈的生日，我和爸爸决定给她做一顿饭。我们一早就去超市买了鱼、鸡蛋和一些新鲜的菜。爸爸负责做汤，我负责做菜。虽然我们做得不太好，家里也有点儿乱，但是妈妈回家看到以后特别感动。最后我们还送给她一个礼物，大家都很开心。","model_py":"Jīntiān shì māma de shēngrì, wǒ hé bàba juédìng gěi tā zuò yí dùn fàn. Wǒmen yì zǎo jiù qù chāoshì mǎi le yú, jīdàn hé yìxiē xīnxiān de cài. Bàba fùzé zuò tāng, wǒ fùzé zuò cài. Suīrán wǒmen zuò de bútài hǎo, jiālǐ yě yǒudiǎnr luàn, dànshì māma huíjiā kàndào yǐhòu tèbié gǎndòng. Zuìhòu wǒmen hái sònggěi tā yí ge lǐwù, dàjiā dōu hěn kāixīn."},{"zh":"请说一说这张图片。","py":"Qǐng shuō yi shuō zhè zhāng túpiàn.","id":"Ceritakan isi gambar ini.","en":"Describe this picture.","sec":120,"pics":["hospital","thermometer","pill","bed"],"model":"上个星期我感冒了，头很疼，还发烧。我量了一下体温，三十八度五，所以我马上去了医院。医生给我检查以后，说问题不大，让我按时吃药，多喝水，多休息。回家以后我在床上睡了一天，第二天就舒服多了。从那以后，我更注意锻炼身体了。","model_py":"Shàng ge xīngqī wǒ gǎnmào le, tóu hěn téng, hái fāshāo. Wǒ liáng le yíxià tǐwēn, sānshíbā dù wǔ, suǒyǐ wǒ mǎshàng qù le yīyuàn. Yīshēng gěi wǒ jiǎnchá yǐhòu, shuō wèntí búdà, ràng wǒ ànshí chīyào, duō hē shuǐ, duō xiūxi. Huíjiā yǐhòu wǒ zài chuángshàng shuì le yìtiān, dì'èrtiān jiù shūfu duō le. Cóng nà yǐhòu, wǒ gèng zhùyì duànliàn shēntǐ le."}],"points":31},{"part":3,"kind":"open","minutes":4,"items":[{"zh":"你觉得周末应该怎么过？为什么？","py":"Nǐ juéde zhōumò yīnggāi zěnme guò? Wèishénme?","id":"Menurutmu bagaimana sebaiknya menghabiskan akhir pekan? Kenapa?","en":"How do you think weekends should be spent? Why?","sec":120,"model":"我觉得周末应该好好放松。平时工作和学习压力都很大，如果周末还一直忙，身体会受不了。所以周末我一般会多睡一会儿，然后去公园散散步，或者和朋友一起吃饭、聊天。有时候我也会去图书馆看看书。这样休息好了，下个星期才有精神工作和学习。","model_py":"Wǒ juéde zhōumò yīnggāi hǎohǎo fàngsōng. Píngshí gōngzuò hé xuéxí yālì dōu hěndà, rúguǒ zhōumò hái yìzhí máng, shēntǐ huì shòu bu liǎo. Suǒyǐ zhōumò wǒ yìbān huì duō shuì yíhuìr, ránhòu qù gōngyuán sàn san bù, huòzhě hé péngyou yìqǐ chīfàn, liáotiān. Yǒu shíhou wǒ yě huì qù túshūguǎn kànkan shū. Zhèyàng xiūxi hǎo le, xià ge xīngqī cái yǒu jīngshén gōngzuò hé xuéxí."},{"zh":"请谈谈你对手机的看法。","py":"Qǐng tántan nǐ duì shǒujī de kànfǎ.","id":"Bagaimana pendapatmu tentang ponsel?","en":"Please give your views on mobile phones.","sec":120,"model":"我认为手机给我们的生活带来了很多方便。我们可以用手机打电话、发信息、上网、买东西，甚至在手机上学习汉语。但是手机也有一些问题。比如有的人一天到晚看手机，眼睛越来越不好，跟家人说话的时间也少了。所以我觉得，手机是有用的，但是我们不应该一直看手机。","model_py":"Wǒ rènwéi shǒujī gěi wǒmen de shēnghuó dàilái le hěnduō fāngbiàn. Wǒmen kěyǐ yòng shǒujī dǎdiànhuà, fā xìnxī, shàngwǎng, mǎi dōngxi, shènzhì zài shǒujī shàng xuéxí Hànyǔ. Dànshì shǒujī yě yǒu yìxiē wèntí. Bǐrú yǒude rén yìtiān-dàowǎn kàn shǒujī, yǎnjing yuèláiyuè bùhǎo, gēn jiārén shuōhuà de shíjiān yě shǎo le. Suǒyǐ wǒ juéde, shǒujī shì yǒuyòng de, dànshì wǒmen bù yīnggāi yìzhí kàn shǒujī."}],"points":31}]},"advanced":{"id":"advanced","hsk":"5-6","prep":10,"minutes":25,"total":100,"pass":60,"set":"B","parts":[{"part":1,"kind":"retell","minutes":8,"items":[{"zh":"从前有个人想买鞋，他先在家里量好了自己脚的大小，写在一张纸上，可是出门的时候忘了带。到了市场，他找到了喜欢的鞋，才发现那张纸留在家里了。他赶紧跑回家去拿，等他再回到市场时，市场已经关门了。别人问他：“你为什么不用自己的脚试一试呢？”他回答说：“我宁可相信量好的尺寸，也不相信自己的脚。”","py":"Cóngqián yǒu ge rén xiǎng mǎi xié, tā xiān zài jiā lǐ liánghǎo le zìjǐ jiǎo de dàxiǎo, xiě zài yì zhāng zhǐ shàng, kěshì chūmén de shíhou wàng le dài. Dào le shìchǎng, tā zhǎodào le xǐhuan de xié, cái fāxiàn nà zhāng zhǐ liú zài jiā lǐ le. Tā gǎnjǐn pǎo huíjiā qù ná, děng tā zài huídào shìchǎng shí, shìchǎng yǐjīng guānmén le. Biérén wèn tā: \"Nǐ wèishénme búyòng zìjǐ de jiǎo shì yi shì ne?\" Tā huídá shuō: \"Wǒ nìngkě xiāngxìn liánghǎo de chǐcùn, yě bù xiāngxìn zìjǐ de jiǎo.\"","id":"Dahulu ada orang yang ingin membeli sepatu. Di rumah ia mengukur kakinya dan menulis ukurannya di selembar kertas, tapi lupa membawanya. Di pasar ia menemukan sepatu yang disukai, lalu sadar kertasnya tertinggal. Ia pulang untuk mengambilnya, tapi saat kembali pasar sudah tutup. Ditanya kenapa tidak mencoba dengan kakinya sendiri, ia menjawab lebih percaya ukuran yang ditulis daripada kakinya.","en":"Long ago a man wanted to buy shoes. At home he measured his foot and wrote the size on a slip of paper, but forgot to take it. At the market he found shoes he liked and realised the paper was at home. He ran back for it, and when he returned the market had closed. Asked why he did not just try the shoes on, he said he trusted the measurement more than his own foot.","sec":120},{"zh":"很多城市都在鼓励人们骑自行车出行。骑自行车不但可以减少空气污染，而且能锻炼身体，还能节省交通费用。为了方便市民，一些城市在地铁站和公交站附近提供了共享自行车，人们用手机就能借车和还车。不过，共享自行车也带来了一些问题，比如有人随便停车，影响了道路交通。因此，城市管理部门需要制定更合理的规定。","py":"Hěnduō chéngshì dōu zài gǔlì rénmen qí zìxíngchē chūxíng. Qí zìxíngchē búdàn kěyǐ jiǎnshǎo kōngqì wūrǎn, érqiě néng duànliàn shēntǐ, hái néng jiéshěng jiāotōng fèiyòng. Wèile fāngbiàn shìmín, yìxiē chéngshì zài dìtiězhàn hé gōngjiāozhàn fùjìn tígōng le gòngxiǎng zìxíngchē, rénmen yòng shǒujī jiù néng jiè chē hé huán chē. Búguò, gòngxiǎng zìxíngchē yě dàilái le yìxiē wèntí, bǐrú yǒurén suíbiàn tíngchē, yǐngxiǎng le dàolù jiāotōng. Yīncǐ, chéngshì guǎnlǐ bùmén xūyào zhìdìng gèng hélǐ de guīdìng.","id":"Banyak kota mendorong orang bersepeda. Bersepeda mengurangi polusi udara, menyehatkan, dan menghemat ongkos transportasi. Beberapa kota menyediakan sepeda sewa bersama dekat stasiun MRT dan halte bus yang bisa dipinjam lewat ponsel. Tapi ada masalah: ada yang parkir sembarangan sehingga mengganggu lalu lintas. Karena itu pengelola kota perlu membuat aturan yang lebih masuk akal.","en":"Many cities encourage cycling. It reduces air pollution, keeps people fit and saves on transport costs. Some cities offer shared bikes near metro and bus stops, borrowed and returned by phone. But some people park them anywhere and block the roads, so city managers need more sensible rules.","sec":120},{"zh":"王阿姨退休以后，开始在社区教孩子们画画。一开始只有三四个孩子来，后来人越来越多，教室都坐不下了。王阿姨从来不收钱，她说看到孩子们认真画画的样子，自己就觉得很幸福。有个孩子以前性格很内向，不爱说话，学了一年画画以后，变得活泼多了，还在全市的比赛中得了奖。孩子的父母特意来感谢王阿姨。","py":"Wáng āyí tuìxiū yǐhòu, kāishǐ zài shèqū jiào háizimen huàhuà. Yì kāishǐ zhǐyǒu sān-sì ge háizi lái, hòulái rén yuèláiyuè duō, jiàoshì dōu zuò bu xià le. Wáng āyí cónglái bù shōu qián, tā shuō kàndào háizimen rènzhēn huàhuà de yàngzi, zìjǐ jiù juéde hěn xìngfú. Yǒu ge háizi yǐqián xìnggé hěn nèixiàng, bú ài shuōhuà, xué le yìnián huàhuà yǐhòu, biàn de huópō duō le, hái zài quánshì de bǐsài zhōng dé le jiǎng. Háizi de fùmǔ tèyì lái gǎnxiè Wáng āyí.","id":"Setelah pensiun, Bibi Wang mulai mengajar anak-anak menggambar di lingkungannya. Awalnya hanya tiga atau empat anak, lalu makin banyak hingga kelas tidak muat. Ia tidak pernah memungut bayaran; melihat anak-anak menggambar dengan serius membuatnya bahagia. Seorang anak yang dulu pendiam menjadi jauh lebih ceria setelah setahun belajar, bahkan menang lomba tingkat kota. Orang tuanya datang khusus berterima kasih.","en":"After retiring, Auntie Wang began teaching children to paint in her neighbourhood. At first only three or four came; later the room could not hold them all. She never charged, saying the sight of them painting made her happy. One shy, quiet child became much livelier after a year and even won a city-wide prize. The child's parents came specially to thank her.","sec":120}],"points":53},{"part":2,"kind":"read","minutes":2,"items":[{"zh":"阅读是一种很好的习惯。通过阅读，我们可以了解不同的文化，认识不同的人，也可以学到在学校里学不到的知识。现在很多人觉得自己太忙，没有时间看书。其实，阅读并不需要很长的时间，每天睡觉以前读二十分钟，一年下来就能读完十几本书。重要的是选择适合自己的书，并且坚持下去。一本好书就像一位好朋友，它会在我们需要的时候给我们安慰和力量。","py":"Yuèdú shì yìzhǒng hěn hǎo de xíguàn. Tōngguò yuèdú, wǒmen kěyǐ liǎojiě bùtóng de wénhuà, rènshi bùtóng de rén, yě kěyǐ xuédào zài xuéxiào lǐ xué bu dào de zhīshí. Xiànzài hěnduō rén juéde zìjǐ tài máng, méi yǒu shíjiān kànshū. Qíshí, yuèdú bìng bù xūyào hěn cháng de shíjiān, měitiān shuìjiào yǐqián dú èrshífēnzhōng, yìnián xiàlái jiù néng dúwán shí jǐ běn shū. Zhòngyào de shì xuǎnzé shìhé zìjǐ de shū, bìngqiě jiānchí xiàqù. Yìběn hǎoshū jiù xiàng yíwèi hǎo péngyou, tā huì zài wǒmen xūyào de shíhou gěi wǒmen ānwèi hé lìliàng.","id":"Membaca adalah kebiasaan yang baik. Dengan membaca kita mengenal budaya dan orang yang berbeda, serta belajar hal yang tidak diajarkan di sekolah. Banyak orang merasa terlalu sibuk untuk membaca. Sebenarnya membaca tidak butuh waktu lama: dua puluh menit sebelum tidur setiap hari, setahun bisa selesai belasan buku. Yang penting memilih buku yang cocok dan konsisten. Buku yang baik seperti sahabat yang memberi penghiburan dan kekuatan saat kita membutuhkannya.","en":"Reading is a good habit. Through it we learn about other cultures and people, and gain knowledge school does not teach. Many feel too busy to read, but twenty minutes before bed each day adds up to a dozen or more books a year. What matters is choosing books that suit you and keeping it up. A good book is like a good friend, offering comfort and strength when we need it.","sec":120}],"points":13},{"part":3,"kind":"open","minutes":5,"items":[{"zh":"你认为年轻人应该先工作还是先读研究生？为什么？","py":"Nǐ rènwéi niánqīngrén yīnggāi xiān gōngzuò háishi xiān dú yánjiūshēng? Wèishénme?","id":"Menurutmu anak muda sebaiknya bekerja dulu atau kuliah S2 dulu? Kenapa?","en":"Should young people work first or do a master's degree first? Why?","sec":150,"model":"我认为这个问题没有标准答案，要根据每个人的情况来决定。如果一个人已经很清楚自己将来想做什么，而且这个专业需要更深的知识，那么先读研究生是一个不错的选择。但是，如果他还不确定自己的兴趣，我建议先工作两三年。在工作中积累经验以后，他会更了解社会的需要，也更明白自己缺少什么。到那时再决定是否读书，目标会更明确，学习的效果也会更好。","model_py":"Wǒ rènwéi zhège wèntí méiyǒu biāozhǔn dá'àn, yào gēnjù měi ge rén de qíngkuàng lái juédìng. Rúguǒ yí ge rén yǐjīng hěn qīngchu zìjǐ jiānglái xiǎng zuò shénme, érqiě zhège zhuānyè xūyào gèng shēn de zhīshí, nàme xiān dú yánjiūshēng shì yí ge búcuò de xuǎnzé. Dànshì, rúguǒ tā hái bú quèdìng zìjǐ de xìngqù, wǒ jiànyì xiān gōngzuò liǎng-sān nián. Zài gōngzuò zhōng jīlěi jīngyàn yǐhòu, tā huì gèng liǎojiě shèhuì de xūyào, yě gèng míngbai zìjǐ quēshǎo shénme. Dào nàshí zài juédìng shìfǒu dúshū, mùbiāo huì gèng míngquè, xuéxí de xiàoguǒ yě huì gèng hǎo."},{"zh":"有人认为城市越大越好，你怎么看？","py":"Yǒurén rènwéi chéngshì yuè dà yuè hǎo, nǐ zěnme kàn?","id":"Ada yang berpendapat makin besar kota makin baik. Bagaimana menurutmu?","en":"Some think the bigger a city, the better. What is your view?","sec":150,"model":"我不完全同意这种看法。大城市确实有很多优点，比如工作机会多，教育和医疗条件好，生活也比较丰富。但是城市太大也会带来不少问题。首先，交通越来越拥挤，很多人每天要花两三个小时在路上。其次，房价太高，年轻人的生活压力很大。另外，环境污染也比较严重。所以我觉得，城市的发展不应该只追求规模，更应该重视居民的生活质量。","model_py":"Wǒ bù wánquán tóngyì zhèzhǒng kànfǎ. Dàchéngshì quèshí yǒu hěnduō yōudiǎn, bǐrú gōngzuò jīhuì duō, jiàoyù hé yīliáo tiáojiàn hǎo, shēnghuó yě bǐjiào fēngfù. Dànshì chéngshì tài dà yě huì dàilái bùshǎo wèntí. Shǒuxiān, jiāotōng yuèláiyuè yōngjǐ, hěnduō rén měitiān yào huā liǎng-sān ge xiǎoshí zài lùshàng. Qícì, fángjià tài gāo, niánqīngrén de shēnghuó yālì hěndà. Lìngwài, huánjìng wūrǎn yě bǐjiào yánzhòng. Suǒyǐ wǒ juéde, chéngshì de fāzhǎn bù yīnggāi zhǐ zhuīqiú guīmó, gèng yīnggāi zhòngshì jūmín de shēnghuó zhìliàng."}],"points":34}]}};
